parameters.jsCode:
const rows = $json.commission_rows;

const tableRows = rows.map(r => `
<tr>
  <td>${r.commission_record_id}</td>
  <td>${r.product_name}</td>
  <td style="text-align:right">${r.quantity}</td>
  <td style="text-align:right">${r.converted_amount_formatted}</td>
  <td style="text-align:right">${r.commission_rate}%</td>
  <td style="text-align:right">${r.commission_amount_formatted}</td>
</tr>
`).join('');

return [{
  json: {
    ...$json,
    commission_table_rows: tableRows
  }
}];

